    static int b[20000];
    static int d[20000];
    static int e[20000];
    int best = 0, i = 0, k = 0, left = 0, length = 0, n = 0, right = 0,
    /* 按边界距离递增算开区间，枚举其中最后戳的 k，使两个子区间可独立求最优。 */
    width = 0;
    n = read();
    a[0] = 1;
    a[(n + 1)] = 1;
    for (i = 1; i < (n + 1); i += 1)  {
        a[i] = read();
    }
